    (103, 'v0.9', 'Lightweight startup version', '/models/compact/v0.9.pt', 2)
ON CONFLICT ("Id") DO NOTHING;

SELECT setval(
    pg_get_serial_sequence('"MoHinh"', 'Id'),
    GREATEST(COALESCE((SELECT MAX("Id") FROM "MoHinh"), 1), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('"PhienBan"', 'Id'),
    GREATEST(COALESCE((SELECT MAX("Id") FROM "PhienBan"), 1), 1),
    true
);
